:root{--bg:#060912;--line:#ffffff12;--text:#f5f7ff;--muted:#8e9ab3;--cyan:#4de2ff;--violet:#8b72ff;--green:#53e0a7;--red:#ff5d7a}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#3927a522,transparent 30%),radial-gradient(circle at 15% 20%,#1bd9ff0d,transparent 28%),var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif}.page{max-width:1450px;margin:auto;padding:16px}.glass{border:1px solid var(--line);background:linear-gradient(145deg,#11192ae8,#080c16e8);border-radius:20px;box-shadow:0 18px 60px #0005;backdrop-filter:blur(18px)}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.brand{display:flex;gap:11px;align-items:center}.orb{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:radial-gradient(circle at 30% 20%,#fff,#755bff 40%,#11142b);box-shadow:0 0 35px #795cff55;animation:float 4s ease-in-out infinite}.brand h1{margin:0;font-size:22px}.brand p{margin:3px 0;color:var(--muted);font-size:11px}.back,.btn,.mini{border:1px solid var(--line);background:#ffffff08;color:#fff;padding:9px 12px;border-radius:11px;text-decoration:none;cursor:pointer}.primary{background:linear-gradient(135deg,#7659ea,#338fff);border-color:transparent}.hero{padding:18px;margin-bottom:12px}.hero h2{margin:3px 0 6px;font-size:23px}.hero p{margin:0;color:var(--muted);font-size:12px;line-height:1.5;max-width:900px}.pills{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.pill{padding:6px 9px;border:1px solid var(--line);border-radius:99px;color:var(--muted);font-size:10px}.pill.on{color:var(--green);border-color:#53e0a744}.layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.65fr);gap:12px}.box{padding:13px}.screen{position:relative;aspect-ratio:16/9;border-radius:16px;overflow:hidden;border:1px solid var(--line);background:#070b15;display:grid;place-items:center}.screen.demo{background:radial-gradient(circle at 60% 40%,#253b68,#0a1020 45%,#050811)}.screen.demo:before{content:"";position:absolute;inset:-25%;background:conic-gradient(from 30deg,transparent,#7c5cff1d,transparent,#36d9ff16,transparent);animation:spin 11s linear infinite}.demo-ui{position:absolute;inset:8%;border:1px solid #fff1;border-radius:14px;background:#070b1590;box-shadow:0 0 50px #4de2ff10;animation:demoFloat 5s ease-in-out infinite}.demo-bar{height:15%;border-bottom:1px solid #fff1;display:flex;align-items:center;gap:7px;padding:0 14px}.demo-dot{width:7px;height:7px;border-radius:50%;background:#ff5d7a;box-shadow:18px 0 #ffc36b,36px 0 #53e0a7}.demo-title{margin-left:auto;color:#8deaff;font-size:9px}.demo-scene{position:absolute;inset:15% 0 0;background:linear-gradient(125deg,#101c35,#17102b 48%,#092633);overflow:hidden}.orb2{position:absolute;width:180px;height:180px;border-radius:50%;left:18%;top:18%;background:radial-gradient(circle at 35% 30%,#fff,#4de2ff44 20%,#7a52ff22 50%,transparent 70%);filter:blur(2px);animation:orb 5s ease-in-out infinite}.wave{position:absolute;left:-10%;right:-10%;height:80px;border-radius:50%;border:1px solid #4de2ff30;animation:wave 4s ease-in-out infinite}.w1{top:40%}.w2{top:55%;animation-delay:-1.2s}.w3{top:70%;animation-delay:-2.1s}.demo-label{position:absolute;left:20px;bottom:17px;padding:7px 10px;border-radius:9px;background:#050810cc;color:#c9d5ea;font-size:10px}.screen video{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;display:none;z-index:3}.screen.live video{display:block}.screen.live .demo-ui{display:none}.guard-layer{position:absolute;inset:0;z-index:5;pointer-events:none}.guard-box{position:absolute;border-radius:10px;background:#05070cd9;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border:1px solid #fff1;box-shadow:0 8px 28px #0005}.guard-box.cover{background:#05070cf2;backdrop-filter:blur(30px)}.scan{position:absolute;inset:0;z-index:4;pointer-events:none;display:none}.scan.on{display:block}.scan:before{content:"";position:absolute;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#4de2ff,#8b72ff,transparent);box-shadow:0 0 18px #4de2ff;animation:scan 1.8s linear infinite}.live-badge{position:absolute;z-index:7;left:10px;top:10px;padding:5px 8px;border-radius:99px;background:#ff385ccc;font-size:9px;display:none}.screen.live .live-badge{display:block}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}.mini.on{color:var(--green);border-color:#53e0a744}.status{display:inline-flex;align-items:center;gap:6px;padding:6px 8px;border-radius:99px;border:1px solid var(--line);font-size:10px;color:var(--muted)}.status.on{color:var(--green);border-color:#53e0a744}.field{margin-top:9px}.field label{display:block;color:var(--muted);font-size:9px;margin-bottom:4px}.field input{width:100%;border:1px solid var(--line);background:#070b14;color:#fff;border-radius:10px;padding:9px;font:inherit;font-size:11px}.guard-card h3,.obs h3{margin:0;font-size:14px}.guard-card p{color:var(--muted);font-size:10px;line-height:1.45}.guard-state{margin:9px 0;padding:10px;border-radius:11px;background:#ffffff05;border:1px solid var(--line);font-size:11px}.obs{margin-top:12px}.obsgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.obs-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.log{margin-top:9px;max-height:150px;overflow:auto;font:10px/1.5 ui-monospace,monospace;color:#aebbd1}.note{margin-top:9px;padding:10px;border:1px dashed #7b66ff35;border-radius:11px;color:var(--muted);font-size:10px;line-height:1.5}@keyframes float{50%{transform:translateY(-5px)}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes demoFloat{50%{transform:translateY(-3px)}}@keyframes orb{50%{transform:translate(55px,-20px) scale(1.1)}}@keyframes wave{50%{transform:translateX(45px) scaleX(1.08)}}@keyframes scan{from{top:0}to{top:100%}}@media(max-width:950px){.layout{grid-template-columns:1fr}}@media(max-width:600px){.page{padding:9px}.obsgrid{grid-template-columns:1fr}.hero h2{font-size:19px}}
</style></head><body><main class="page"><header class="head"><div class="brand"><div class="orb">✦</div><div><h1>Creator Guard</h1><p>Evruni • AI-фильтр для OBS</p></div></div><a class="back" href="/">← Evruni</a></header>
<section class="hero glass"><h2>Смотрим фильм — Evruni Guard следит сам</h2><p>Один модуль вместо набора повторяющихся инструментов. Экран остаётся локально. AI получает только маленькие кадры при изменении сцены и возвращает координаты для blur/cover и beep.</p><div class="pills"><span id="pGuard" class="pill">● Guard: выключен</span><span id="pObs" class="pill">● OBS: офлайн</span><span class="pill">⚡ кадр 320×180</span><span class="pill">🧠 без постоянного видеопотока</span></div></section>
<section class="layout"><section class="glass box"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><b>🖥️ Экран — демонстрация прямо здесь</b><button class="btn primary" id="share">▶ Выбрать экран</button></div><div id="screen" class="screen demo"><span class="live-badge">● LIVE PREVIEW</span><div class="demo-ui"><div class="demo-bar"><span class="demo-dot"></span><span class="demo-title">EVRUNI STREAM • AI GUARD</span></div><div class="demo-scene"><div class="orb2"></div><div class="wave w1"></div><div class="wave w2"></div><div class="wave w3"></div><div class="demo-label">Анимированная демонстрация • локально</div></div></div><video id="video" autoplay muted playsinline></video><div class="scan" id="scan"></div><div id="guardLayer" class="guard-layer"></div></div><div class="actions"><button class="mini" id="guardBtn">🛡️ Авто Guard</button><button class="mini" id="clearGuard">Очистить фильтр</button><button class="mini" id="clip">✂️ Сохранить клип</button><button class="mini" id="stop">⏹ Остановить экран</button></div></section>
<aside class="glass box guard-card"><h3>🎬 Что смотрим?</h3><p>Название даёт AI контекст, но решение принимается по текущему кадру. Поэтому не нужно вручную искать сцены.</p><div class="field"><label>Фильм / сериал</label><input id="title" maxlength="120" placeholder="Например: The Last of Us"></div><div class="field"><label>Источник звука в OBS для beep</label><input id="audioSource" maxlength="120" placeholder="Например: Movie Audio"></div><div class="guard-state" id="guardState"><b>Готов.</b><br>Выбери экран и запусти Guard.</div><div class="note">Оптимизация: 320×180 JPEG, максимум 1 AI-запрос примерно в 2,2 сек и только после заметной смены кадра. Кадры не сохраняются.</div><div class="obs glass box"><div style="display:flex;justify-content:space-between;align-items:center"><h3>🎛️ OBS</h3><span id="obsStatus" class="status">● офлайн</span></div><div class="obsgrid"><div class="field"><label>Host</label><input id="obsHost" value="127.0.0.1"></div><div class="field"><label>Port</label><input id="obsPort" value="4455"></div><div class="field"><label>Пароль OBS</label><input id="obsPass" type="password" autocomplete="off"></div></div><div class="obs-actions"><button class="mini" id="obsConnect">Подключить</button><button class="mini" id="addOverlay">Добавить Guard в OBS</button><button class="mini" id="startStream">▶ Эфир</button><button class="mini" id="startRecord">● Запись</button></div><div id="obsLog" class="log"></div></div></aside></section>
<section class="glass box" style="margin-top:12px"><b>Как это работает</b><div class="note">Браузер показывает экран локально → уменьшает кадр → отправляет только изменившийся кадр vision-модели → получает координаты чувствительной зоны → рисует blur в preview и отправляет то же событие в OBS Browser Source. При beep Guard кратко приглушает выбранный аудиовход OBS и запускает локальный короткий сигнал.</div></section></main>
<script>
(()=>{const API='/api/creator_guard.php',CSRF=document.querySelector('meta[name="csrf-token"]').content,$=s=>document.querySelector(s);let media=null,guard=false,timer=0,busy=false,lastHash='',ws=null,identified=false,rid=0,pending=new Map(),obsOnline=false;const log=t=>{const d=document.createElement('div');d.textContent=new Date().toLocaleTimeString()+' — '+t;$('#obsLog').prepend(d)};function state(t){$('#guardState').innerHTML='<b>'+t+'</b>';$('#pGuard').textContent='● Guard: '+(guard?'онлайн':'выключен');$('#pGuard').className='pill '+(guard?'on':'')}function draw(boxes){const r=$('#guardLayer');r.innerHTML='';(boxes||[]).forEach(b=>{const d=document.createElement('div');d.className='guard-box '+(b.action==='cover'?'cover':'');d.style.left=(b.x/10)+'%';d.style.top=(b.y/10)+'%';d.style.width=(b.w/10)+'%';d.style.height=(b.h/10)+'%';r.appendChild(d)})}function beepLocal(){try{const C=AudioContext||webkitAudioContext,a=new C,o=a.createOscillator(),g=a.createGain();o.frequency.value=880;g.gain.value=.0001;o.connect(g).connect(a.destination);o.start();g.gain.exponentialRampToValueAtTime(.13,a.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+.18);o.stop(a.currentTime+.2)}catch(_){}}async function sha(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return btoa(String.fromCharCode(...new Uint8Array(b)))}async function connectObs(){if(ws&&identified)return;const h=$('#obsHost').value.trim()||'127.0.0.1',p=$('#obsPort').value.trim()||'4455';try{ws=new WebSocket('ws://'+h+':'+p);ws.onmessage=async e=>{let m;try{m=JSON.parse(e.data)}catch(_){return}if(m.op===0){const d=m.d||{},id={rpcVersion:1};if(d.authentication){const s=await sha($('#obsPass').value+d.authentication.salt),a=await sha(atob(s)+d.authentication.challenge);id.authentication=a}ws.send(JSON.stringify({op:1,d:id}))}else if(m.op===2){identified=true;obsOnline=true;$('#obsStatus').textContent='● онлайн';$('#obsStatus').className='status on';$('#pObs').textContent='● OBS: онлайн';$('#pObs').className='pill on';log('OBS подключён')}else if(m.op===7){const x=pending.get(m.d.requestId);if(x){pending.delete(m.d.requestId);m.d.requestStatus?.result?x.resolve(m.d.responseData||{}):x.reject(new Error(m.d.requestStatus?.comment||'OBS error'))}}};ws.onclose=()=>{identified=false;obsOnline=false;$('#obsStatus').textContent='● офлайн';$('#obsStatus').className='status';$('#pObs').textContent='● OBS: офлайн';$('#pObs').className='pill'};ws.onerror=()=>log('OBS WebSocket ошибка')}catch(e){log(e.message)}}function req(type,data={}){return new Promise((resolve,reject)=>{if(!ws||!identified)return reject(new Error('OBS не подключён'));const id='eg'+(++rid);pending.set(id,{resolve,reject});ws.send(JSON.stringify({op:6,d:{requestType:type,requestId:id,requestData:data}}))})}async function broadcast(data){try{await req('BroadcastCustomEvent',{eventData:{eventName:'EvruniCreator',eventData:data}})}catch(e){log('Overlay: '+e.message)}}async function muteBeep(){const src=$('#audioSource').value.trim();if(!src||!obsOnline)return beepLocal();try{const q=await req('GetInputMute',{inputName:src}),was=!!q.inputMuted;if(!was){await req('SetInputMute',{inputName:src,inputMuted:true});setTimeout(()=>req('SetInputMute',{inputName:src,inputMuted:false}).catch(()=>{}),650)}beepLocal()}catch(_){beepLocal()}}function hashFrame(ctx){const d=ctx.getImageData(0,0,32,18).data;let s='';for(let i=0;i<d.length;i+=16)s+=((d[i]+d[i+1]+d[i+2])/3)>90?'1':'0';return s}function changed(a,b){if(!a||!b)return true;let n=0;for(let i=0;i<a.length;i++)if(a[i]!==b[i])n++;return n>Math.max(5,a.length*.12)}async function analyze(){if(!guard||busy||!media)return;const c=document.createElement('canvas');c.width=320;c.height=180;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage($('#video'),0,0,320,180);const h=hashFrame(x);if(!changed(h,lastHash))return;lastHash=h;busy=true;$('#scan').classList.add('on');state('AI проверяет кадр…');try{const image=c.toDataURL('image/jpeg',.34),r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({image,title:$('#title').value.trim()})}),j=await r.json();if(!r.ok)throw new Error(j.error||'Guard error');draw(j.boxes||[]);await broadcast({type:'guard',boxes:j.boxes||[],beep:!!j.beep});if(j.beep)await muteBeep();state(j.boxes?.length?'⚠️ Чувствительный фрагмент скрыт':'✓ Кадр чист')}catch(e){state('Ошибка Guard: '+e.message)}finally{busy=false;$('#scan').classList.remove('on')}}async function share(){if(media){media.getTracks().forEach(t=>t.stop());media=null;$('#screen').classList.remove('live');$('#video').srcObject=null;return}try{media=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:12},audio:false});$('#video').srcObject=media;$('#screen').classList.add('live');media.getVideoTracks()[0].addEventListener('ended',()=>{media=null;$('#screen').classList.remove('live');if(guard)toggleGuard()});log('Экран выбран локально')}catch(_){log('Выбор экрана отменён')}}async function toggleGuard(){guard=!guard;$('#guardBtn').classList.toggle('on',guard);$('#guardBtn').textContent=guard?'● Guard запущен':'🛡️ Авто Guard';state(guard?'Guard включён':'Guard выключен');if(guard&&!media){guard=false;$('#guardBtn').classList.remove('on');return state('Сначала выбери экран')}if(timer)clearInterval(timer);if(guard){lastHash='';timer=setInterval(analyze,2200);analyze()}else{draw([]);broadcast({type:'clear'})}}$('#share').onclick=share;$('#guardBtn').onclick=toggleGuard;$('#clearGuard').onclick=()=>{draw([]);broadcast({type:'clear'});state('Фильтр очищен')};$('#clip').onclick=()=>req('SaveReplayBuffer').then(()=>log('Replay Buffer сохранён')).catch(e=>log('Клип: '+e.message));$('#stop').onclick=()=>{if(media){media.getTracks().forEach(t=>t.stop());media=null}$('#screen').classList.remove('live')};$('#obsConnect').onclick=connectObs;$('#addOverlay').onclick=async()=>{try{await connectObs();await new Promise(r=>setTimeout(r,300));const s=await req('GetCurrentProgramScene'),name=s.sceneName;if(!name)throw new Error('Нет активной сцены');const h=$('#obsHost').value.trim()||'127.0.0.1',p=$('#obsPort').value.trim()||'4455',url=location.origin+'/creator-guard-overlay.php#host='+encodeURIComponent(h)+'&port='+encodeURIComponent(p)+'&pass='+encodeURIComponent($('#obsPass').value||''),list=await req('GetInputList'),exists=(list.inputs||[]).some(x=>x.inputName==='Evruni Guard Overlay');if(!exists)await req('CreateInput',{sceneName:name,inputName:'Evruni Guard Overlay',inputKind:'browser_source',inputSettings:{url,width:1920,height:1080,fps:30},sceneItemEnabled:true});else await req('SetInputSettings',{inputName:'Evruni Guard Overlay',inputSettings:{url,width:1920,height:1080,fps:30}});log('Guard Overlay добавлен в сцену')}catch(e){log('Overlay: '+e.message)}};$('#startStream').onclick=()=>req('StartStream').then(()=>log('Эфир запущен')).catch(e=>log(e.message));$('#startRecord').onclick=()=>req('StartRecord').then(()=>log('Запись запущена')).catch(e=>log(e.message));})();
</script></body></html>